<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Forms;

use Override;
use Psr\Http\Message\ResponseInterface;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\OAuth\Theme\Application\DecorateHtml;
use Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Services\HtmlSecurer;
use Civi\Lughauth\Features\OAuth\Authentication\Application\AuthenticateUser;
use Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Services\PublicMfa;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepInput;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepName;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\Exception\LoginException;
use Civi\Lughauth\Shared\Infrastructure\Translation\MessageProvider;

/**
 * Login step form that challenges an already-enrolled user with a TOTP one-time password.
 *
 * This form is shown after successful credential authentication when the user has MFA enabled
 * and the ChallengesState does not yet carry a satisfied MFA flag. It presents a single OTP
 * code input field. If the ChallengesState already carries withMfa=true (e.g. the session was
 * resumed), the authentication phase skips the OTP check and proceeds immediately.
 *
 * On submission, the OTP is verified via PublicMfa. A valid code updates the challenges state
 * with withMfa=true and calls AuthenticateUser::preAuthenticate to produce the pre-auth result.
 * An invalid code throws a LoginException with an ERR_MFA_REQUIRED result so the form is
 * re-rendered with a wrong-code error message.
 *
 * Relationships: uses PublicMfa for OTP verification, calls AuthenticateUser for post-MFA
 * pre-authentication, relies on HtmlSecurer for CSRF injection and auto-focus scripts, and
 * DecorateHtml for themed page output.
 */
class UseMfaForm implements StepForm
{
    public function __construct(
        private readonly MessageProvider $messages,
        private readonly AuthenticateUser $authenticator,
        private readonly PublicMfa $publicMfa,
        private readonly DecorateHtml $decorator,
        private readonly HtmlSecurer $securer
    ) {
    }

    /**
     * Renders the OTP entry form with a single code input and a back link.
     *
     * Injects CSRF signing and auto-focus scripts and displays any error from the previous
     * failed OTP attempt as a localised message above the input field.
     */
    #[Override]
    public function render(StepInput $input, ResponseInterface $response, ?AuthenticationResult $error): StepResult
    {
        $locale = '';

        $js = $this->securer->configureScripts([
            $this->securer->addSign("sign"),
            $this->securer->focusOn("mfa_code")
        ]);
        $translator = $this->messages->messages('forms', $locale, __DIR__ . '/../../Translations');

        $title = $translator->get("mfa.title");
        $errorMessage = $error?->errorMessage;
        $error = $errorMessage !== null && $errorMessage !== ''
            ? $translator->get("mfa.error-format", [$translator->get('error.' . strtolower($errorMessage))])
            : '';

        $help = $translator->get("mfa.help");
        $code = $translator->get("mfa.code");
        $send = $translator->get("mfa.send");

        $backLabel = $translator->get("mfa.back-label");
        $backText = $translator->get(
            "mfa.back-text",
            ["<input class=\"inline\" type=\"submit\" value=\"" . $backLabel . "\" />"]
        );
        $error = $error !== '' ? '<p class="error">' . $error . '</p>' : '';
        $step = StepName::MFA->value;
        $response->getBody()->write($this->decorator->getFullPage(
            $input->request,
            'Mfa',
            $js . <<<HTML
                    <h1>{$title}</h1>
                    <p>{$help}</p>
                    {$error}
                    <form method="POST">
                        <input type="hidden" name="csid" id="sign" />
                        <input type="hidden" name="step" value="{$step}" />
                        <label> {$code}
                            <input type="text" name="mfa_code" id="mfa_code" value="" />
                        </label>
                        <input class="primary-button" type="submit" value="{$send}" />
                    </form>
                    <form method="POST">
                        <input type="hidden" name="step" value="" />
                        {$backText}
                    </form>
                HTML,
            $locale,
            'index',
            $input->context->tenant
        ));
        return StepResult::render($response, $input->challenges);
    }

    /**
     * Validates the submitted OTP code and pre-authenticates the user on success.
     *
     * If the challenges state already indicates MFA was satisfied (e.g. session resume),
     * the OTP check is bypassed. Otherwise the code is verified via PublicMfa, the challenges
     * state is updated with withMfa=true, and preAuthenticate is called to continue the flow.
     */
    #[Override]
    public function authenticate(StepInput $input): StepResult
    {
        $csid = (string) ($input->body['csid'] ?? '');
        $challenges = $input->challenges;

        if ($challenges->withMfa) {
            $auth = $this->authenticator->preAuthenticate(
                $input->authRequest,
                $challenges,
                $input->context->tenant,
                $input->context->issuer,
                $csid,
                $input->context->state,
                $input->context->nonce
            );
            return StepResult::proceed($auth, $challenges);
        }

        $otp = $input->body['mfa_code'] ?? '';
        if ($this->publicMfa->verifyOtp($input->context->tenant, $challenges->username ?? '', $otp)) {
            $updated = $challenges->withMfa(true);
            $auth = $this->authenticator->preAuthenticate(
                $input->authRequest,
                $updated,
                $input->context->tenant,
                $input->context->issuer,
                $csid,
                $input->context->state,
                $input->context->nonce
            );
            return StepResult::proceed($auth, $updated);
        }

        throw new LoginException(auth: AuthenticationResult::mfaRequired('wrong_auth_code'));
    }
}
